('c6d398ec-2528-48fe-ab20-2e470c3257f1','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Marrakech SARL','Royal Concierge Marrakech','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',7.8,92.7,13,4.8,'active'),
('96de7336-4c54-4238-b79e-5693be2cdfb7','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Marrakech SARL','Local Eyes Marrakech','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',0.9,96.5,164,4,'active'),
('2c2f28d0-e810-4676-985d-d0e721b382c6','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',11.1,98.4,325,4.8,'active'),
('23bfe13b-09cc-477c-a02f-282e21964eb9','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',5,88.3,100,4,'active'),
('86440ca0-c75e-438e-b26d-75f327410950','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Marrakech Cooking School SARL','Dar Marrakech Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',2.5,93.2,291,4.9,'active'),
('77e097b5-e85f-4f1a-b8ff-647ed169d72c','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',9.4,88.3,262,4.7,'active'),
('4888ebfc-3889-4e3f-a884-855b95697523','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atelier Lumière SARL','Atelier Lumière','workshop',4,'verified',ARRAY['en','fr','es'],'A luxury creative studio offering private masterclasses with acclaimed Moroccan artists. Photography, calligraphy, and perfume-making in a beautifully restored medina house.',11.4,95.7,61,3.5,'active'),
('7ad8f57d-b0d3-49d3-9666-784bad2f97eb','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Marrakech Budget SARL','Riad Marrakech Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',5.7,92.8,69,3.9,'active'),
('d9ade4dc-85f7-4b4c-bbba-7e2bf8a50cb1','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Marrakech Boutique SARL','Dar Marrakech Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',4,95.1,389,4.3,'active'),
('607db36e-95ce-44c7-b5ec-b0ea2f73d888','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Marrakech Royal SARL','Palais Marrakech Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',10,88.6,404,4.4,'active'),
('5dbcead6-7c21-4f54-8499-7beca4278ee1','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Marrakech Tours SARL','Street Food Marrakech Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',9.8,97.5,133,4.9,'active'),
('9865901e-8091-4f1f-b9cc-8a84ad1ce7cf','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Marrakech Family Kitchen SARL','Table Marrakech Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',2.1,93.4,122,4.8,'active'),
('ed16c49d-6081-47af-854f-a76e61b773ca','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Marrakech SARL','Le Salon Marrakech','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',7.5,98.6,45,4.2,'active'),
('e486c385-0870-4d3f-ab24-c891995f9af6','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Marrakech Adventure Club SARL','Marrakech Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',5.4,98.1,98,3.8,'active'),
('cbe83bfa-ef42-465b-bf3e-d81930f8eac0','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Extreme Sports SARL','Atlas Extreme Sports','activity',3,'verified',ARRAY['en','fr','de'],'Adrenaline specialists — quad biking, sandboarding, paragliding, and canyoning. Professional instructors, top safety record, and GoPro footage included.',7.3,88.4,246,4.6,'active'),
('a2bdef82-e9e3-48d8-80f7-53d0e0ea8f02','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Sahara Wellness Retreat SARL','Sahara Wellness Retreat','activity',3,'verified',ARRAY['en','fr'],'A wellness sanctuary offering hammam, massage, yoga, and meditation sessions. Organic argan oil treatments and sound healing in a tranquil garden setting.',8.3,98.5,443,3.7,'active'),
('834f4ece-1358-4d92-968b-71274f29d6aa','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Desert Nomad Tours SARL','Desert Nomad Tours','desert_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'A Berber family business running camel treks and overnight camps in the dunes since 2005. Basic but authentic — real nomad-style camps with woven tents and campfire music.',6.5,97,343,4.9,'active'),
