('8011097d-c7fc-48b4-bb4b-54c9d2fe9ec7','MA','a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',2.5,93.2,270,3.7,'active'),
